// Provided for lab 14.2 as its benchmark baseline. You do not edit this file (CUDA; also built
// for HIP and for both CPU emulators). It is lab 14.1's part B: if you have not written lab
// 14.1 yet, do that first, because this file is its answer.
//
// The design of section 14.5 (Figs. 14.6 and 14.7, pp. 336-339): one thread per key, one bit
// per pass, and every key written straight to its global destination. Fig. 14.7 is one kernel
// that calls a grid-wide scan in the middle; here it is cut into three launches per bit
// (extract, the provided scan of scan.cu, scatter), because a scan across blocks inside one
// kernel would need blocks to wait for one another (notes/today/ch14-facts.md C4).
//
//   void launchRadixSortOneBitGlobal(unsigned int* keys, unsigned int* vals,
//                                    unsigned int* tmpKeys, unsigned int* tmpVals,
//                                    unsigned int* bits, unsigned int* scanScratch, int n)
//       Stable LSD sort of n (key, value) pairs by the 32-bit key, 32 passes, result in
//       keys/vals. bits holds n + 1 entries; scanScratch holds scanScratchCount(n + 1).

// Provided in scan.cu.
int scanScratchCount(int count);
void launchExclusiveScan(unsigned int* data, int count, unsigned int* scratch);

// bits[i] = bit `bit` of keys[i]; bits[n] = 0, so the scan of n + 1 entries ends with the total.
__global__ void onebitExtractKernel(const unsigned int* keys, unsigned int* bits, unsigned int n, unsigned int bit) {
    const unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        bits[i] = (keys[i] >> bit) & 1u;
    } else if (i == n) {
        bits[n] = 0u;
    }
}

// Zeros go to (index - ones before), ones to (n - ones in total + ones before): Fig. 14.6.
__global__ void onebitScatterKernel(const unsigned int* keysIn, const unsigned int* valsIn, unsigned int* keysOut,
                                    unsigned int* valsOut, const unsigned int* onesBefore, unsigned int n,
                                    unsigned int bit) {
    const unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        const unsigned int key = keysIn[i];
        const unsigned int b = (key >> bit) & 1u;
        const unsigned int before = onesBefore[i];
        const unsigned int total = onesBefore[n];
        const unsigned int dst = b == 0 ? i - before : n - total + before;
        keysOut[dst] = key;
        valsOut[dst] = valsIn[i];
    }
}

void launchRadixSortOneBitGlobal(unsigned int* keys, unsigned int* vals, unsigned int* tmpKeys, unsigned int* tmpVals,
                                 unsigned int* bits, unsigned int* scanScratch, int n) {
    if (n < 1) {
        return;
    }
    const unsigned int count = (unsigned int)n;
    const unsigned int block = 256;
    unsigned int* keysIn = keys;
    unsigned int* valsIn = vals;
    unsigned int* keysOut = tmpKeys;
    unsigned int* valsOut = tmpVals;
    for (unsigned int bit = 0; bit < 32; ++bit) {
        onebitExtractKernel<<<(count + 1 + block - 1) / block, block>>>(keysIn, bits, count, bit);
        launchExclusiveScan(bits, n + 1, scanScratch);
        onebitScatterKernel<<<(count + block - 1) / block, block>>>(keysIn, valsIn, keysOut, valsOut, bits, count, bit);
        unsigned int* swap = keysIn; keysIn = keysOut; keysOut = swap;
        swap = valsIn; valsIn = valsOut; valsOut = swap;
    }
    // 32 passes swap the buffers an even number of times: the result is back in keys/vals.
}
